import numpy as np

def schedule(decisions, minutes, available):
    d = np.asarray(decisions, dtype=float)
    t = np.asarray(minutes, dtype=float)
    if d.ndim != 1 or t.shape != d.shape or not np.isin(d, [0,1]).all():
