import numpy as np

def backlog(arrivals, capacities):
    a, c = np.asarray(arrivals, dtype=float), np.asarray(capacities, dtype=float)
    if a.ndim != 1 or c.shape != a.shape:
        raise ValueError("Use aligned one-dimensional counts")
    for x in (a,c):
        if not np.isfinite(x).all() or (x < 0).any() or (x != np.floor(x)).any():
            raise ValueError("Counts must be finite nonnegative integers")
    waiting = 0
    trace = []
    for incoming, slots in zip(a,c):
        waiting = max(0, waiting + int(incoming) - int(slots))
        trace.append(waiting)
    return np.asarray(trace, dtype=int)

