def select_sources(chunks, allowed, window, reserved, output):
    def whole(v):
        return type(v) is int and v >= 0
    def nonempty(v):
        return isinstance(v, str) and bool(v.strip())
    if any(not whole(v) for v in (window, reserved, output)) or reserved + output > window:
        raise ValueError("Invalid budget")
    if not isinstance(allowed, list) or any(not nonempty(a) for a in allowed) or not isinstance(chunks, list):
        raise ValueError("Invalid records or permissions")
    for row in chunks:
        if not isinstance(row, dict) or not nonempty(row.get("id")) or not nonempty(row.get("asset")) or not whole(row.get("tokens")):
            raise ValueError("Invalid chunk")
    budget = window - reserved - output
    used, selected = 0, []
    for row in chunks:
        if row["asset"] not in allowed:
            continue
        if used + row["tokens"] > budget:
            break
        selected.append(row["id"])
        used += row["tokens"]
    return selected

